const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const uid=()=>((window.crypto&&typeof window.crypto.randomUUID==='function')?window.crypto.randomUUID():`id-${Date.now()}-${Math.random().toString(16).slice(2)}`);
const euro=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:'EUR'}).format(Number(n||0));
const euro3=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:'EUR',minimumFractionDigits:3,maximumFractionDigits:3}).format(Number(n||0));
const num=(n,d=1)=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:d});
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=s=>s?new Date(s).toLocaleDateString(undefined,{day:'2-digit',month:'short',year:'numeric'}):'—';
function formObject(form){const out={};new FormData(form).forEach((v,k)=>{out[k]=v});return out}
function readFileText(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(r.error||new Error('Could not read file'));r.readAsText(file)})}

let state={route:'dashboard',vehicles:[],fillups:[],promos:[],settings:{},editing:null,prefill:null,priceResults:[],deferredPrompt:null,userPos:null,searchCenter:null,priceCountry:null,priceMeta:null,priceFuels:[]};
let priceMap=null;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
async function setting(key,fallback=null){const r=await FuelDB.get('settings',key);return r&&r.value!==undefined?r.value:fallback}
async function setSetting(key,value){await FuelDB.put('settings',{key,value});state.settings[key]=value}
async function refresh(){state.vehicles=await FuelDB.all('vehicles');state.fillups=(await FuelDB.all('fillups')).sort((a,b)=>new Date(b.date)-new Date(a.date));state.promos=(await FuelDB.all('promos'))||[];for(const k of ['activeVehicle','fuelTypeId','lastBackup','priceCountry','promoFillLitres','suggestBtn'])state.settings[k]=await setting(k,null)}
function activeVehicle(){return state.vehicles.find(v=>v.id===state.settings.activeVehicle)||state.vehicles[0]||null}
function vehicleFillups(id){return state.fillups.filter(f=>f.vehicleId===id).sort((a,b)=>new Date(a.date)-new Date(b.date))}
function calcMetrics(v){const fs=vehicleFillups(v&&v.id);if(!fs.length)return{distance:0,litres:0,cost:0,avg:null,costKm:null,last:null};const last=fs[fs.length-1],distance=Math.max(0,(last&&last.odometer||0)-(fs[0]&&fs[0].odometer||0)),litres=fs.reduce((s,f)=>s+Number(f.litres||0),0),cost=fs.reduce((s,f)=>s+Number(f.totalCost||0),0);let fullDistance=0,fullLitres=0,lastFull=null,acc=0;for(const f of fs){acc+=Number(f.litres||0);if(f.fullTank){if(lastFull){fullDistance+=Number(f.odometer)-Number(lastFull.odometer);fullLitres+=acc}lastFull=f;acc=0}}return{distance,litres,cost,avg:fullDistance>0?fullLitres/fullDistance*100:null,costKm:distance>0?cost/distance:null,last:last}}
function route(name){state.route=name;state.editing=null;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===name));render()}
const ROUTE_LABEL={dashboard:'Home',add:'Add fill-up',history:'History',prices:'Prices',settings:'Settings'};
function updateSuggestBtn(){const b=$('#suggestBtn');if(!b)return;const hidden=state.settings.suggestBtn===false;b.classList.toggle('hidden',hidden);if(!hidden)b.href='mailto:nuno.f.pedrosa@gmail.com?subject='+encodeURIComponent('[Fuel suggestion]')+'&body='+encodeURIComponent('Page: '+(ROUTE_LABEL[state.route]||state.route)+'\n\nSuggestion: ')}
function wrap(kicker,title,body){return `<div class="kicker">${kicker}</div><h1 class="title">${title}</h1>${body}`}
function fillRow(f){const v=state.vehicles.find(x=>x.id===f.vehicleId);return `<div class="row"><div><strong>${dateLabel(f.date)}</strong><div class="muted">${esc(v&&v.name||'Vehicle')} ${f.station?'· '+esc(f.station):''}</div></div><div><strong>${num(f.odometer,0)} km</strong><div class="muted">odometer</div></div><div><strong>${num(f.litres,2)} L</strong><div class="muted">${f.fullTank?'full tank':'partial'}</div></div><div><strong>${euro(f.totalCost)}</strong><div class="muted">${f.pricePerLitre?euro3(f.pricePerLitre)+'/L':''}</div></div><div class="actions-inline"><button class="icon-btn" data-edit="${f.id}">✎</button><button class="icon-btn danger-link" data-delete="${f.id}">×</button></div></div>`}
function dashboard(){const v=activeVehicle();if(!v)return wrap('Private by design','Welcome to FuelLog',`<div class="empty">Add a vehicle in Settings to begin.</div>`);const m=calcMetrics(v),recent=state.fillups.filter(f=>f.vehicleId===v.id).slice(0,5);return `<div class="hero"><div class="hero-card"><h1>${esc(v.name)}</h1><p>${[v.make,v.model,v.registration].filter(Boolean).map(esc).join(' · ')}</p><div class="hero-metric">${m.avg?num(m.avg,2):'—'} <small>L/100 km average</small></div></div><div class="side-card"><div><div class="kicker">Latest fill-up</div><div class="big">${m.last?euro(m.last.totalCost):'No entries'}</div><p class="muted">${m.last?`${num(m.last.litres,2)} L · ${dateLabel(m.last.date)}`:'Add your first fill-up.'}</p></div><button class="btn" data-route="add">+ Add fill-up</button></div></div><div class="grid"><div class="stat"><div class="label">Distance logged</div><div class="value">${num(m.distance,0)} km</div></div><div class="stat"><div class="label">Fuel logged</div><div class="value">${num(m.litres,1)} L</div></div><div class="stat"><div class="label">Total spend</div><div class="value">${euro(m.cost)}</div></div><div class="stat"><div class="label">Cost / km</div><div class="value">${m.costKm?euro(m.costKm):'—'}</div></div></div><div class="section-head"><h2>Recent fill-ups</h2><button class="btn secondary" data-route="history">View all</button></div>${recent.length?`<div class="list">${recent.map(fillRow).join('')}</div>`:`<div class="empty">No fill-ups yet.</div>`}`}
function fillForm(){const v=activeVehicle(),f=Object.assign({},state.editing||{},state.prefill||{});state.prefill=null;const now=new Date(),local=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,16);return wrap(f.id?'Edit entry':'New entry',f.id?'Edit fill-up':'Add fill-up',`<div class="card form-card"><form id="fillForm"><input type="hidden" name="stationId" value="${esc(f.stationId||'')}"><input type="hidden" name="country" value="${esc(f.country||'')}"><input type="hidden" name="fuelId" value="${esc(f.fuelId||'')}"><div class="form-grid"><div class="field"><label>Vehicle</label><select name="vehicleId" required>${state.vehicles.map(x=>`<option value="${x.id}" ${(f.vehicleId||(v&&v.id))===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Date & time</label><input type="datetime-local" name="date" value="${(f.date||local).slice(0,16)}" required></div><div class="field"><label>Odometer (km)</label><input type="number" step="1" min="0" name="odometer" value="${f.odometer!=null?f.odometer:''}" required></div><div class="field"><label>Litres</label><input type="number" step="0.001" min="0" name="litres" value="${f.litres!=null?f.litres:''}" required></div><div class="field"><label>Total cost (€)</label><input type="number" step="0.01" min="0" name="totalCost" value="${f.totalCost!=null?f.totalCost:''}" required></div><div class="field"><label>Price / litre (€)</label><input type="number" step="0.001" min="0" name="pricePerLitre" value="${f.pricePerLitre!=null?f.pricePerLitre:''}"></div><div class="field"><label>Station</label><input name="station" value="${esc(f.station||'')}" placeholder="Optional"></div><div class="field"><label>Fuel type</label><input name="fuelType" value="${esc(f.fuelType||(v&&v.fuelType)||'')}" placeholder="Gasóleo simples"></div><div class="switchline"><input type="checkbox" name="fullTank" ${f.fullTank!==false?'checked':''}><label>Full tank</label></div><div class="field full"><label>Notes</label><textarea name="notes">${esc(f.notes||'')}</textarea></div></div><div class="form-actions"><button type="button" class="btn ghost" data-route="history">Cancel</button><button class="btn">Save fill-up</button></div></form></div>`)}
function history(){return wrap('Your records','History',`<div class="toolbar"><select id="historyVehicle"><option value="all">All vehicles</option>${state.vehicles.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><input id="historySearch" placeholder="Search station or notes"></div><div class="section-head"><h2>${state.fillups.length} fill-ups</h2><button class="btn" data-route="add">+ Add</button></div><div id="historyList" class="list">${state.fillups.length?state.fillups.map(fillRow).join(''):`<div class="empty">Nothing logged yet.</div>`}</div>`)}
function proxyUrl(){return (window.FUELLOG_CONFIG&&window.FUELLOG_CONFIG.stationProxy)||null}
const round3=n=>Math.round(n*1000)/1000;
async function searchProxy(dataset,fuel,center,radiusKm){const r=await fetch(new URL(proxyUrl(),location.href),{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',cache:'no-store',body:JSON.stringify({provider:dataset,fuel:String(fuel),lat:round3(center.lat),lon:round3(center.lon),radius:radiusKm})});if(!r.ok)throw new Error('Proxy returned '+r.status);return r.json()}
function defaultPriceCountry(){const l=((navigator.languages&&navigator.languages[0])||navigator.language||'').toUpperCase(),m=l.match(/-([A-Z]{2})/),code=m?m[1]:l;return FuelProviders.countries().some(c=>c.code===code)?code:'PT'}
function priceProvider(){const cc=state.priceCountry||defaultPriceCountry();return FuelProviders.stationProvider(cc)||FuelProviders.referenceProvider(cc)}
const COUNTRY_VIEW={PT:[39.6,-8.0,6],ES:[40.2,-3.7,6],FR:[46.6,2.4,6],BE:[50.6,4.6,8],NL:[52.2,5.3,7]};
const PRICE_TYPE_LABEL={station:'current station price','official-maximum':'official maximum','national-average':'national average'};
function provLabel(s){if(!s.provenance)return'';const p=FuelProviders.byId(s.provenance.sourceId);return[(p&&p.name)||s.provenance.sourceId,PRICE_TYPE_LABEL[s.provenance.priceType]||s.provenance.priceType].filter(Boolean).join(' · ')}
function proxyStation(provider,s,fuel,sourceUpdatedAt,retrievedAt){return{id:provider.id+':'+s.id,country:provider.country,name:s.name,brand:s.brand,address:s.address,town:s.town,updated:s.updated||'',lat:s.lat,lon:s.lon,price:s.price,unit:(provider.units&&provider.units[fuel])||'litre',distance:s.distance,provenance:{sourceType:provider.sourceType,sourceId:provider.id,priceType:provider.priceType,sourceUpdatedAt:FuelProviders.localIso(s.updated)||sourceUpdatedAt||null,retrievedAt:retrievedAt}}}
