function renderStations(){const meta=state.priceMeta||{},ss=state.priceResults||[],hasPromo=(state.promos||[]).length>0;if(hasPromo){ss.forEach(s=>{s._eff=stationEff(s)});ss.sort((a,b)=>((a._eff.price==null?Infinity:a._eff.price)-(b._eff.price==null?Infinity:b._eff.price))||((isFinite(a.distance)?a.distance:Infinity)-(isFinite(b.distance)?b.distance:Infinity)))}$('#priceSummary').innerHTML=`<h2>${ss.length} stations</h2><span class="muted">sorted by ${hasPromo?'effective price':'price'}${meta.label||''}${meta.retrievedAt?' · Retrieved '+FuelProviders.ago(meta.retrievedAt):''}${meta.stale?' · stale':''}</span>`;$('#stationList').innerHTML=ss.length?ss.slice(0,100).map(stationHtml).join(''):`<div class="empty">No stations found.</div>`;$$('#stationList [data-log-station]').forEach(b=>b.onclick=()=>logFillAt(+b.dataset.logStation));if(priceMap)updateMap()}
