function settingsPage(){const av=activeVehicle();return wrap('Local-first','Settings & data',`<div class="settings-grid"><div class="card"><div class="section-head"><h2>Vehicles</h2><button id="addVehicle" class="btn secondary">+ Vehicle</button></div><div id="vehicles">${state.vehicles.length?state.vehicles.map(v=>`<div class="vehicle-card"><div><strong>${esc(v.name)}</strong><div class="muted">${[v.make,v.model,v.registration,v.preferredFuel?FuelLogFuels.label(v.preferredFuel):''].filter(Boolean).map(esc).join(' · ')}</div></div><div class="actions-inline"><button class="icon-btn" data-vehicle-active="${v.id}">${av&&av.id===v.id?'★':'☆'}</button><button class="icon-btn" data-vehicle-edit="${v.id}">✎</button><button class="icon-btn danger-link" data-vehicle-delete="${v.id}">×</button></div></div>`).join(''):`<div class="empty">Add your first vehicle.</div>`}</div></div><div class="card"><div class="section-head"><h2>Brand promos</h2><button id="addPromo" class="btn secondary">+ Promo</button></div><div id="promos">${(state.promos||[]).length?state.promos.slice().sort((a,b)=>String(a.brand).localeCompare(String(b.brand))).map(promoRow).join(''):`<div class="empty">No promos yet.</div>`}</div><div class="field" style="margin-top:12px"><label>Typical fill (L) — used to compare per-fill discounts</label><input id="promoFillLitres" type="number" step="1" min="1" value="${promoFillLitres()}"></div><p class="muted">Promos match the station's brand exactly (accents and case ignored). Stations with a matching promo show an effective price and are sorted by it.</p></div><div class="card"><h2>Backup & portability</h2><p class="muted">Full JSON backup is the safest format. Import also accepts generic JSON, CSV, semicolon CSV, TSV and delimited TXT files.</p><div class="list"><button id="exportJson" class="btn">Export JSON backup</button><button id="exportCsv" class="btn secondary">Export fill-ups CSV</button><label class="btn ghost" style="text-align:center">Import data<input id="importData" type="file" accept=".json,.csv,.tsv,.txt,application/json,text/csv,text/tab-separated-values,text/plain" hidden></label></div><p class="muted">Imports recognise common English and Portuguese headings such as date/data, odometer/quilometragem, litres/litros, cost/custo and station/posto. Decimal commas are supported.</p><p class="muted">Last backup: ${state.settings.lastBackup?dateLabel(state.settings.lastBackup):'never'}</p></div><div class="card"><h2>Feedback</h2><div class="switchline" style="padding-top:0"><input type="checkbox" id="suggestEnabled" ${state.settings.suggestBtn===false?'':'checked'}><label for="suggestEnabled">Show the floating ✉ suggestion button (top right)</label></div><p class="muted">Opens your email app with a pre-addressed suggestion message that names the page you were on. Nothing is sent until you press send.</p></div></div><div class="section-head"><h2>Privacy</h2></div><div class="card"><p><strong>Your log stays on this device.</strong> Vehicles, fill-ups, notes and settings are stored in IndexedDB. FuelLog has no application database on the server.</p><p class="muted">Clearing browser/site storage can erase local records, so keep periodic JSON backups. On older iPhones, exporting a backup before clearing Safari data is especially important.</p></div>`)}
