function flexBool(v){const s=String(v==null?'':v).toLowerCase().trim();return ['1','true','yes','y','sim','s','full','cheio'].indexOf(s)>=0}
function flexDate(v){if(v instanceof Date&&!isNaN(v.getTime()))return v.toISOString();const s=String(v||'').trim();if(!s)return null;const m=s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/);if(m){let y=+m[3];if(y<100)y+=2000;const d=new Date(y,+m[2]-1,+m[1],+(m[4]||0),+(m[5]||0),+(m[6]||0));if(!isNaN(d.getTime()))return d.toISOString()}const d=new Date(s);return isNaN(d.getTime())?null:d.toISOString()}
function guessDelimiter(text){const line=(text.split(/\r?\n/).find(x=>x.trim())||'');const choices=['\t',';',','];let best=',',count=-1;choices.forEach(d=>{let c=0,q=false;for(let i=0;i<line.length;i++){if(line[i]==='"')q=!q;else if(!q&&line[i]===d)c++}if(c>count){count=c;best=d}});return best}
function parseDelimited(text,delimiter){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i];if(q){if(ch==='"'&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"')q=false;else cell+=ch}else if(ch==='"')q=true;else if(ch===delimiter){row.push(cell);cell=''}else if(ch==='\n'){row.push(cell);rows.push(row);row=[];cell=''}else if(ch!=='\r')cell+=ch}row.push(cell);if(row.some(x=>String(x).trim()!==''))rows.push(row);if(rows.length<2)return[];const head=rows.shift().map((h,i)=>String(h||('column_'+(i+1))).trim());return rows.filter(r=>r.some(x=>String(x).trim()!=='')).map(r=>{const o={};head.forEach((h,i)=>o[h]=r[i]===undefined?'':r[i]);return o})}
function extractRowsFromJson(data){if(Array.isArray(data))return data;if(data&&Array.isArray(data.fillups))return data.fillups;if(data&&Array.isArray(data.records))return data.records;if(data&&Array.isArray(data.entries))return data.entries;if(data&&Array.isArray(data.data))return data.data;return[]}
async function ensureVehicleByName(name,fuelType){const clean=String(name||'').trim();if(!clean)return activeVehicle();let v=state.vehicles.find(x=>String(x.name||'').toLowerCase()===clean.toLowerCase());if(v)return v;v={id:uid(),name:clean,registration:'',make:'',model:'',fuelType:String(fuelType||''),initialOdometer:0};await FuelDB.put('vehicles',v);state.vehicles.push(v);return v}
async function importGenericRows(rows,replace){const valid=[],bad=[];for(let i=0;i<rows.length;i++){const r=rows[i]||{};const date=flexDate(rowValue(r,['date','datetime','timestamp','data','data_hora','datahora']));const odometer=flexNum(rowValue(r,['odometer','odometer_km','mileage','km','kms','quilometragem','conta_quilometros']));const litres=flexNum(rowValue(r,['litres','liters','litros','quantity','volume','combustivel_litros']));let total=flexNum(rowValue(r,['total_cost_eur','total_cost','total','cost','amount','custo','custo_total','preco_total','valor']));let price=flexNum(rowValue(r,['price_per_litre','price_per_liter','price_l','unit_price','price','preco_litro','preco_por_litro']));if(!isFinite(total)&&isFinite(price)&&isFinite(litres))total=price*litres;if(!isFinite(price)&&isFinite(total)&&isFinite(litres)&&litres>0)price=total/litres;if(!date||!isFinite(odometer)||!isFinite(litres)||litres<=0||!isFinite(total)){bad.push(i+2);continue}valid.push({raw:r,date,odometer,litres,total,price})}if(!valid.length)throw new Error('No usable fuel records were detected. Check the column headings.');const msg='Detected '+rows.length+' rows: '+valid.length+' usable'+(bad.length?', '+bad.length+' skipped':'')+'.\n\nPress OK to continue importing.';if(!confirm(msg))return 0;if(replace){await FuelDB.clear('fillups');await FuelDB.clear('vehicles');state.vehicles=[];state.fillups=[]}const existing={};state.fillups.forEach(f=>{existing[[f.vehicleId,f.date,Number(f.odometer),Number(f.litres)].join('|')]=1});let count=0;for(const x of valid){const r=x.raw,fuelType=String(rowValue(r,['fuel_type','fuel','combustivel','tipo_combustivel'])||''),fuelIdRaw=String(rowValue(r,['fuel_id','fuelid','combustivel_id'])||'').trim(),stationId=String(rowValue(r,['station_id','stationid'])||'').trim(),countryRaw=String(rowValue(r,['country','pais','país'])||'').trim().toUpperCase(),vehicleName=String(rowValue(r,['vehicle','vehicle_name','car','car_name','viatura','veiculo'])||'').trim();let v=await ensureVehicleByName(vehicleName,fuelType);if(!v){v={id:uid(),name:'Imported vehicle',registration:'',make:'',model:'',fuelType:fuelType,initialOdometer:0};await FuelDB.put('vehicles',v);state.vehicles.push(v)}const key=[v.id,x.date,Number(x.odometer),Number(x.litres)].join('|');if(existing[key])continue;const sourceId=String(rowValue(r,['id','uuid','record_id'])||'').trim();await FuelDB.put('fillups',{id:sourceId||uid(),vehicleId:v.id,date:x.date,odometer:x.odometer,litres:x.litres,totalCost:x.total,pricePerLitre:isFinite(x.price)?x.price:(x.total/x.litres),station:String(rowValue(r,['station','gas_station','fuel_station','posto','posto_abastecimento'])||'').trim(),stationId:stationId||undefined,country:/^[A-Z]{2}$/.test(countryRaw)?countryRaw:undefined,fuelId:FuelLogFuels.LIST.some(x=>x.id===fuelIdRaw)?fuelIdRaw:(FuelLogFuels.guess(fuelType)||undefined),fuelType:fuelType,fullTank:flexBool(rowValue(r,['full_tank','full','tank_full','deposito_cheio','ateste'])),notes:String(rowValue(r,['notes','note','comment','comments','notas','observacoes'])||'').trim(),updatedAt:new Date().toISOString()});existing[key]=1;count++}if(!state.settings.activeVehicle&&state.vehicles.length)await setSetting('activeVehicle',state.vehicles[0].id);return count}
async function importFuelLogBackup(data,replace){if(data.format!=='FuelLog'||!Array.isArray(data.vehicles)||!Array.isArray(data.fillups))throw new Error('Invalid FuelLog backup');if(replace){await FuelDB.clear('vehicles');await FuelDB.clear('fillups');await FuelDB.clear('promos')}for(const v of data.vehicles)await FuelDB.put('vehicles',v);for(const f of data.fillups)await FuelDB.put('fillups',f);for(const p of data.promos||[])await FuelDB.put('promos',p);for(const settingRec of data.settings||[])if(settingRec.key!=='lastBackup')await FuelDB.put('settings',settingRec);return data.fillups.length}
async function migrateData(force){if(!force&&(await setting('schemaMigrated',0))>=2)return;for(const v of state.vehicles)if(v.preferredFuel===undefined){v.preferredFuel=FuelLogFuels.guess(v.fuelType)||null;await FuelDB.put('vehicles',v)}for(const f of state.fillups)if(f.fuelId===undefined){const v=state.vehicles.find(x=>x.id===f.vehicleId);f.fuelId=FuelLogFuels.guess(f.fuelType)||(v&&v.preferredFuel)||null;await FuelDB.put('fillups',f)}const ftid=await setting('fuelTypeId',null);if(ftid!=null&&(await setting('priceFuel:PT',null))==null)await setSetting('priceFuel:PT',ftid);if(!force)await setSetting('schemaMigrated',2)}
async function importData(e){const file=e.target.files&&e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('For older iPhones, import files are limited to 5 MB. Split a larger history into smaller files.');const text=await readFileText(file);const trimmed=text.replace(/^\uFEFF/,'').trim();if(!trimmed)throw new Error('The selected file is empty.');const lower=String(file.name||'').toLowerCase();let data=null,rows=null,isBackup=false;if(lower.endsWith('.json')||trimmed[0]==='{'||trimmed[0]==='['){data=JSON.parse(trimmed);isBackup=!!(data&&data.format==='FuelLog'&&Array.isArray(data.fillups));if(!isBackup)rows=extractRowsFromJson(data)}else rows=parseDelimited(trimmed,guessDelimiter(trimmed));const replace=confirm('Import mode:\n\nOK = replace local vehicles and fill-ups\nCancel = merge with existing data');let count;if(isBackup)count=await importFuelLogBackup(data,replace);else count=await importGenericRows(rows||[],replace);await refresh();await migrateData(true);render();toast('Imported '+count+' fill-ups')}catch(err){alert('Import failed: '+err.message)}finally{e.target.value=''}}
async function init(){await FuelDB.open();await refresh();if(!state.vehicles.length){const first={id:uid(),name:'My car',registration:'',make:'',model:'',fuelType:'Gasóleo simples',initialOdometer:0};await FuelDB.put('vehicles',first);await setSetting('activeVehicle',first.id);await refresh()}await migrateData();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(console.error);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredPrompt=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').onclick=async()=>{if(!state.deferredPrompt)return;state.deferredPrompt.prompt();await state.deferredPrompt.userChoice;state.deferredPrompt=null;$('#installBtn').classList.add('hidden')};const status=()=>$('#offlineBadge').textContent=navigator.onLine?'Online':'Offline ready';window.addEventListener('online',status);window.addEventListener('offline',status);status();$$('[data-route]',document).forEach(b=>b.onclick=()=>route(b.dataset.route))}
init().catch(e=>{$('#app').innerHTML=`<div class="empty">FuelLog could not start: ${esc(e.message)}</div>`;console.error(e)});
